(()=>{const i=document.querySelector('#toolSearch');if(!i)return;const k=()=>{requestAnimationFrame(()=>{i.scrollTop=i.scrollHeight;requestAnimationFrame(()=>{i.scrollTop=i.scrollHeight})});setTimeout(()=>{i.scrollTop=i.scrollHeight},80)};i.addEventListener('input',k);i.addEventListener('focus',k);i.addEventListener('scroll',()=>{if(i.scrollTop<0)i.scrollTop=0},{passive:true})})();
